mapper.select:
SELECT b."itemId" AS "itemId", i."itemCode" AS "itemCode", i."itemName" AS "itemName", i."unit" AS "unit", b."batchNo" AS "batchNo", s."warehouseId" AS "warehouseId", w."warehouseName" AS "warehouseName", b."productionDate" AS "productionDate", b."expiryDate" AS "expiryDate", (b."expiryDate" - CURRENT_DATE) AS "daysLeft", s."quantity" AS "quantity", (s."quantity" - s."preAllocatedQty") AS "availableQty" FROM "Batch" b JOIN "Item" i ON i."id" = b."itemId" JOIN "Stock" s ON s."batchId" = b."id" JOIN "Warehouse" w ON w."id" = s."warehouseId" WHERE b."expiryDate" IS NOT NULL AND b."expiryDate" <= CURRENT_DATE + #{alertDays} AND s."quantity" > 0
AND s."warehouseId" = #{query.warehouseId}
AND b."itemId" = #{query.itemId}
ORDER BY b."expiryDate" ASC, s."id" ASC
